<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';
import {FileText,Upload,Eye,Copy} from 'lucide-vue-next';
import {ElMessage} from 'element-plus';
import {api,get,message} from '../api';
import {label,date} from '../fulfillment';
import {useAuth} from '../stores/auth';
import ContractTemplatePreview from '../components/ContractTemplatePreview.vue';
const auth=useAuth(),rows=ref<any[]>([]),error=ref(''),q=ref(''),type=ref(''),status=ref(''),applied=ref({q:'',type:'',status:''}),dialog=ref(false),busy=ref(false),loading=ref(false),page=ref(1),preview=ref(false),selected=ref<any>(),file=ref<File>(),formError=ref('');
const form=ref<any>({type:'MAIN',name:'',body:'',mode:'A',effectiveFrom:new Date().toISOString()});
const filtered=computed(()=>rows.value.filter(r=>`${r.name}${r.file?.name||''}`.includes(applied.value.q)&&(!applied.value.type||r.type===applied.value.type)&&(!applied.value.status||r.status===applied.value.status)));
const cards=computed(()=>filtered.value.slice((page.value-1)*9,page.value*9));
function search(){applied.value={q:q.value,type:type.value,status:status.value};page.value=1;}
function reset(){q.value='';type.value='';status.value='';search();}
async function load(){loading.value=true;try{rows.value=(await get<any[]>('/contracts/templates')).sort((a,b)=>new Date(b.createdAt).getTime()-new Date(a.createdAt).getTime()||b.version-a.version);error.value='';}catch(e){error.value=message(e);}finally{loading.value=false;}}
function create(r?:any){form.value={type:r?.type||'MAIN',name:r?.name||'',body:r?.body||'',fileId:r?.fileId||undefined,mode:r?.mode||'A',effectiveFrom:new Date().toISOString()};file.value=undefined;formError.value='';dialog.value=true;}
function choose(upload:any){file.value=upload.raw;if(!form.value.name)form.value.name=file.value?.name.replace(/\.[^.]+$/,'');}
async function save(){if(!form.value.name?.trim()||form.value.name.trim().length<2||!form.value.effectiveFrom){formError.value='请填写模板名称与生效时间';return;}if(!file.value&&!form.value.fileId&&form.value.body?.trim().length<10){formError.value='请上传合同模板文件';return;}busy.value=true;formError.value='';try{if(file.value){const data=new FormData();for(const key of ['name','type','mode','effectiveFrom'])data.append(key,form.value[key]);if(form.value.body?.trim())data.append('body',form.value.body);data.append('file',file.value);await api.post('/contracts/templates/upload',data);}else await api.post('/contracts/templates',form.value);dialog.value=false;await load();page.value=1;ElMessage.success('模板草稿已保存，可预览后发布');}catch(e){formError.value=message(e);}finally{busy.value=false;}}
async function publish(r:any){busy.value=true;try{await api.post(`/contracts/templates/${r.id}/publish`);await load();ElMessage.success('模板版本已发布');}catch(e){error.value=message(e);}finally{busy.value=false;}}
function inspect(r:any){selected.value=r;preview.value=true;}
const size=(n:number)=>n>=1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';
onMounted(load);
</script>
<template><div class="page-actions"><el-button v-if="auth.can('contract-template:write')" type="primary" @click="create()"><Upload :size="15"/>上传合同模板</el-button></div><el-alert v-if="error" :title="error" type="error" class="form-error" :closable="false"/><div class="filter-panel"><el-form inline @submit.prevent="search"><el-form-item label="模板名称"><el-input v-model="q" clearable placeholder="名称 / 文件名" @keyup.enter="search"/></el-form-item><el-form-item label="模板类型"><el-select v-model="type" clearable placeholder="全部类型"><el-option label="运输主合同" value="MAIN"/><el-option label="平台附加合同" value="ADDENDUM"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="status" clearable placeholder="全部状态"><el-option label="草稿" value="DRAFT"/><el-option label="已发布" value="PUBLISHED"/></el-select></el-form-item><el-form-item class="filter-actions"><el-button type="primary" plain @click="search">搜索</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form></div><div class="template-panel" v-loading="loading"><div class="list-toolbar"><strong>合同模板 <b>{{filtered.length}}</b></strong></div><div v-if="!error&&cards.length" class="template-grid"><article v-for="r in cards" :key="r.id" class="template-card"><div class="template-cover" @click="inspect(r)"><div class="mini-document"><FileText :size="36" :stroke-width="1.3"/><span>{{r.file?.name?.split('.').at(-1)?.toUpperCase()||'TEXT'}}</span><i/><i/><i/></div><el-tag :type="r.status==='PUBLISHED'?'success':'info'" effect="light">{{label(r.status)}}</el-tag></div><div class="template-info"><h3>{{r.name}}</h3><p class="template-kind">{{label(r.type)}}<span>V{{r.version}}</span></p><div class="template-meta"><span>模板文件</span><strong :title="r.file?.name">{{r.file?.name||'内置条款正文'}}</strong><span>上传时间</span><strong>{{date(r.createdAt)}}</strong><span>生效时间</span><strong>{{date(r.effectiveFrom)}}</strong><span>签署规则</span><strong>{{r.type==='MAIN'?'贸易方与承运方':r.mode==='A'?'双方确认':'贸易方、承运方、平台'}}</strong></div><small v-if="r.file" class="file-size">{{size(r.file.size)}}</small><div class="template-actions"><el-button link type="primary" @click="inspect(r)"><Eye :size="14"/>预览</el-button><el-button v-if="auth.can('contract-template:write')" link @click="create(r)"><Copy :size="13"/>复制新版本</el-button><el-button v-if="r.status==='DRAFT'&&auth.can('contract-template:write')" link type="primary" :loading="busy" @click="publish(r)">发布模板</el-button></div></div></article></div><el-empty v-else-if="!error&&!loading" :description="applied.q||applied.type||applied.status?'未找到符合条件的模板':'暂无合同模板，上传文件后可预览和发布'"/><div class="pagination"><span>共 {{filtered.length}} 个模板版本</span><el-pagination v-model:current-page="page" :total="filtered.length" :page-size="9" layout="prev,pager,next"/></div></div><el-dialog v-model="dialog" :title="form.fileId?'复制模板新版本':'上传合同模板'" width="720px" :close-on-click-modal="false" destroy-on-close><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top"><div class="form-grid"><el-form-item label="合同模板名称" required><el-input v-model="form.name" maxlength="100" placeholder="如：粮食多式联运运输合同"/></el-form-item><el-form-item label="模板类型" required><el-select v-model="form.type"><el-option label="运输主合同" value="MAIN"/><el-option label="平台附加合同" value="ADDENDUM"/></el-select></el-form-item><el-form-item label="生效时间" required><el-date-picker v-model="form.effectiveFrom" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ"/></el-form-item><el-form-item v-if="form.type==='ADDENDUM'" label="签署规则"><el-select v-model="form.mode"><el-option label="A · 贸易方与承运方确认" value="A"/><el-option label="B · 贸易方、承运方、平台签署" value="B"/></el-select></el-form-item></div><el-form-item label="上传模板文件" :required="!form.fileId"><el-upload drag :auto-upload="false" :show-file-list="false" accept=".pdf,.docx,.txt" :on-change="choose" class="template-upload"><Upload :size="28"/><p>{{file?.name||'点击选择或拖入合同文件'}}</p><small>PDF / DOCX / TXT · 最大 8MB</small></el-upload></el-form-item><p v-if="form.fileId&&!file" class="muted">沿用原版本附件；选择新文件可替换本版本附件。</p><el-form-item v-if="!file" label="条款正文"><el-input v-model="form.body" type="textarea" :rows="5" maxlength="30000" placeholder="原有文本模板可继续编辑条款"/></el-form-item><p class="muted">成交数量、路线、费用与签约企业信息会在生成合同时追加。已发布版本和已生成合同保留原文件。</p></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存模板草稿</el-button></template></el-dialog><ContractTemplatePreview v-model="preview" :template="selected" :source="selected?.fileId?`/contracts/templates/${selected.id}/file`:undefined"/></template>
<style scoped>.template-panel{background:#fff;border:1px solid var(--border);border-radius:8px;padding:22px}.template-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.template-card{border:1px solid #e2e6ec;border-radius:8px;overflow:hidden;background:#fff;transition:box-shadow .15s}.template-card:hover{box-shadow:0 4px 16px #1c25340c}.template-cover{height:150px;background:linear-gradient(125deg,#f4f5f8,#fdf5f5);display:flex;align-items:center;justify-content:center;position:relative;cursor:pointer}.template-cover>.el-tag{position:absolute;top:16px;right:16px}.mini-document{width:104px;height:122px;background:white;border:1px solid #e4e5e9;border-radius:3px;box-shadow:4px 4px 0 #fff8f8;display:flex;align-items:center;flex-direction:column;padding:13px;color:#d64c54}.mini-document>span{font-size:10px;margin:5px 0;color:#8c94a0}.mini-document i{width:65px;border-top:2px solid #e7e9ee;margin:4px}.mini-document i:last-child{width:43px;align-self:flex-start}.template-info{padding:20px}.template-info h3{font-size:16px;line-height:1.7;margin:0;overflow-wrap:anywhere}.template-kind{display:flex;justify-content:space-between;font-size:12px;color:#8993a0;margin:8px 0 18px}.template-kind>span{color:#cb454e;background:#fff2f3;padding:2px 8px;border-radius:3px}.template-meta{display:grid;grid-template-columns:65px minmax(0,1fr);gap:13px 10px;font-size:12px}.template-meta>span{color:#9199a5}.template-meta>strong{font-weight:400;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#596371}.file-size{display:block;color:#a2a9b3;font-size:11px;margin-top:12px}.template-actions{display:flex;align-items:center;gap:14px;border-top:1px solid #edf0f3;margin-top:18px;padding-top:14px}.template-actions .el-button{margin:0;font-size:12px}.template-actions svg{margin-right:4px}.template-upload{width:100%}.template-upload p{margin:12px 0 8px}.template-upload small{color:#99a1ad}.template-upload svg{color:#dc6067}.pagination{margin-top:20px}.page-actions svg{margin-right:7px}@media(max-width:1280px){.template-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.template-grid{grid-template-columns:1fr}.template-panel{padding:16px}}</style>
